-- A pool on a sheet: a name (trimmed, once per sheet) and its members.
CREATE TABLE pool (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(64)  NOT NULL REFERENCES sheet (id),
    name     VARCHAR(100) NOT NULL
);
CREATE UNIQUE INDEX pool_sheet_name ON pool (sheet_id, name);

-- A pool's member: a person on the sheet, in the pool at most once, with a share percent (more than
-- 0.00, at most 100.00). A person may be in several pools.
CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id   BIGINT       NOT NULL REFERENCES pool (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    share     DECIMAL(5, 2) NOT NULL
);
CREATE UNIQUE INDEX pool_member_pool_person ON pool_member (pool_id, person_id);
-- A pool's member may be another pool instead of a person, with a share like a person's. A pool is a
-- member of at most one pool; exactly one of person_id and member_pool_id is set.
ALTER TABLE pool_member ALTER COLUMN person_id SET NULL;
ALTER TABLE pool_member ADD COLUMN member_pool_id BIGINT REFERENCES pool (id);
ALTER TABLE pool_member ADD CONSTRAINT pool_member_one_kind
    CHECK ((person_id IS NULL) <> (member_pool_id IS NULL));
CREATE UNIQUE INDEX pool_member_member_pool ON pool_member (member_pool_id);
-- A pool membership may carry a from-date and a to-date, each optional: the member counts toward the
-- pool's total share and gets a cut only on days within them. A to-date is never before the from-date.
ALTER TABLE pool_member ADD COLUMN from_date DATE;
ALTER TABLE pool_member ADD COLUMN to_date DATE;
ALTER TABLE pool_member ADD CONSTRAINT pool_member_to_after_from
    CHECK (to_date IS NULL OR from_date IS NULL OR to_date >= from_date);

